"""Read-only in-memory flight QA. Never writes player progress."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]
html=(root/'outputs/NOSTRAVECTOR_Main_Menu.html').read_text(encoding='utf-8')
guard="const nativeFlightStorage=window.localStorage;Object.defineProperty(window,'localStorage',{configurable:true,value:{getItem:key=>nativeFlightStorage.getItem(key),setItem(){throw Error('Read-only flight QA');},removeItem(){throw Error('Read-only flight QA');}}});"
html=html.replace('<script>','<script>'+guard,1)
base="""const flightPreview=NVAntarctica.fresh(124);Object.assign(flightPreview,{jamesIntroductionDone:true,stationFound:true,stationDialogueDone:true,hazardStage:'complete',jamesCarQuoteShown:true,supplyDialogueDone:true,suppliesPlanKnown:true,ferryDialogueDone:true,ferryPlanKnown:true,bedBuilt:true,bedRested:true,dreamDone:true,betrayalStage:'complete',ferryEscaped:true,jamesGone:true});NVAntarctica.grantWakeInventory(flightPreview);NVAfrica.arrive(flightPreview);flightPreview.africaStage='complete';flightPreview.friendQuest='recruited';flightPreview.friendDialogueDone=true;flightPreview.spaceshipFound=true;flightPreview.space=NVSpace.fresh();"""
for name,setup in {'earth':"flightPreview.space.body='earth';flightPreview.space.phase='atmosphere';flightPreview.space.geo={lat:-28,lon:18,altitude:28000,heading:0,look:-.28,global:true,course:null,landing:false,orbit:false};NVWorldFlight.syncPosition(flightPreview);",'mars':"flightPreview.space.body='mars';flightPreview.space.phase='atmosphere';flightPreview.space.geo={lat:15,lon:50,altitude:22000,heading:0,look:-.28,global:true,course:null,landing:false,orbit:false};NVWorldFlight.syncPosition(flightPreview);"}.items():
 fixture=base+setup+"savedGame=validCharacterSave({id:'temporary-flight-preview',wanderer:{...DEFAULT_WANDERER,name:'The Wanderer'},progress:{chapter:3,checkpoint:'flight-preview',antarctica:NVAntarctica.snapshot(flightPreview)}});savedWanderer=savedGame.wanderer;startAntarctica();soundtrack.setEnabled(false);$('#saveWorld').disabled=true;"
 fixture+="""const flightControls=document.createElement('div');flightControls.id='flightQA';flightControls.style='position:fixed;top:12px;left:38%;z-index:90;display:flex;gap:5px;background:#071827;padding:5px;';const advance=document.createElement('button');advance.textContent='ADVANCE JOURNEY 30 S';advance.onclick=()=>{if(!surfaceAtlasOpen&&!spaceChartOpen&&!gamePaused){for(let i=0;i<600;i++)tickSpace(.05);updatePolarHUD();}};flightControls.append(advance);const hide=document.createElement('button');hide.textContent='HIDE QA CONTROLS';hide.onclick=()=>flightControls.style.display='none';flightControls.append(hide);document.body.append(flightControls);"""
 at=html.rfind('</script>');(root/f'outputs/world-flight-{name}-qa.html').write_text(html[:at]+fixture+html[at:],encoding='utf-8')
print('Created Earth/Mars atmospheric QA without persistent save writes.')
